import torch
from torch.utils.cpp_extension import load_inline

# CUDA source implementing a simple tiled FP16 GEMM.
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <int TILE>
__global__ void matmul_fp16_kernel(const __half* __restrict__ A,
                                   const __half* __restrict__ B,
                                   __half* __restrict__ C,
                                   int N) {
    // Compute global row and column this thread is responsible for
    int row = blockIdx.y * TILE + threadIdx.y;
    int col = blockIdx.x * TILE + threadIdx.x;

    float acc = 0.0f;   // accumulation in FP32 for accuracy

    // Loop over tiles of the K dimension
    for (int t = 0; t < N; t += TILE) {
        __shared__ __half As[TILE][TILE];
        __shared__ __half Bs[TILE][TILE];

        // Load a tile of A into shared memory
        if (row < N && (t + threadIdx.x) < N) {
            As[threadIdx.y][threadIdx.x] = A[row * N + t + threadIdx.x];
        } else {
            As[threadIdx.y][threadIdx.x] = __float2half(0.0f);
        }

        // Load a tile of B into shared memory
        if ((t + threadIdx.y) < N && col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[(t + threadIdx.y) * N + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = __float2half(0.0f);
        }

        __syncthreads();

        // Compute partial product for this tile
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc += __half2float(As[threadIdx.y][k]) *
                   __half2float(Bs[k][threadIdx.x]);
        }

        __syncthreads();
    }

    // Write result back to global memory
    if (row < N && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

// Wrapper callable from Python
void matmul_fp16(torch::Tensor A, torch::Tensor B, torch::Tensor C) {
    const int N = A.size(0);
    constexpr int TILE = 32;
    const dim3 threads(TILE, TILE);
    const dim3 blocks((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);

    const __half* A_ptr = reinterpret_cast<const __half*>(A.data_ptr<at::Half>());
    const __half* B_ptr = reinterpret_cast<const __half*>(B.data_ptr<at::Half>());
    __half* C_ptr = reinterpret_cast<__half*>(C.data_ptr<at::Half>());

    // Launch kernel (dispatch works for half scalar type)
    matmul_fp16_kernel<TILE><<<blocks, threads>>>(A_ptr, B_ptr, C_ptr, N);
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA error in matmul_fp16: %s\\n", cudaGetErrorString(err));
    }
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_fp16", &matmul_fp16, "FP16 matrix multiplication (CUDA)");
}
'''

# Compile the extension inline
_matmul_ext = load_inline(
    name='matmul_fp16_ext',
    cpp_sources='',
    cuda_sources=cuda_source,
    functions=['matmul_fp16'],
    verbose=False,
)

class ModelNew(torch.nn.Module):
    """
    Drop‑in replacement for the reference model that uses a custom CUDA
    kernel to compute C = A @ B with FP16 tensors.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.dtype == torch.float16 and B.dtype == torch.float16, \
            "ModelNew expects FP16 inputs"
        assert A.shape == B.shape and A.dim() == 2, \
            "Inputs must be square matrices of the same size"
        C = torch.empty_like(A)
        _matmul_ext.matmul_fp16(A, B, C)
        return C

# Example helper functions matching the reference API
def get_inputs():
    N = 2048 * 2
    A = torch.rand(N, N, dtype=torch.float16, device='cuda')
    B = torch.rand(N, N, dtype=torch.float16, device='cuda')
    return [A, B]

def get_init_inputs():
    return []  # No special initialization required
